package com.example.gestor_documental.service.impl;
import com.example.gestor_documental.enums.*;import com.example.gestor_documental.exception.AccesoDenegadoException;import com.example.gestor_documental.model.*;import com.example.gestor_documental.repository.*;import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class JustificanteProvisionalServiceTest{@Test void clienteAjenoNoPuedeAcceder(){SolicitudRepository solicitudes=mock(SolicitudRepository.class);JustificanteProvisionalRepository justificantes=mock(JustificanteProvisionalRepository.class);JustificanteProvisionalService service=new JustificanteProvisionalService(solicitudes,justificantes);Cliente propietario=cliente(1L),ajeno=cliente(2L);Solicitud s=new Solicitud();ReflectionTestUtils.setField(s,"id",10L);s.setCliente(propietario);when(solicitudes.findById(10L)).thenReturn(Optional.of(s));Usuario u=new Usuario();u.setRolUsuario(RolUsuario.CLIENTE);u.setCliente(ajeno);assertThrows(AccesoDenegadoException.class,()->service.obtener(10L,u));assertThrows(AccesoDenegadoException.class,()->service.solicitar(10L,u));verifyNoInteractions(justificantes);}private Cliente cliente(Long id){Cliente c=new Cliente();ReflectionTestUtils.setField(c,"id",id);c.setNif("N"+id);c.setNombre("C"+id);c.setEmail(id+"@x.es");return c;}}
